CREATE TYPE myrange28 AS RANGE (
  SUBTYPE = int4,
  SUBTYPE_OPCLASS = int4_ops
);

CREATE TYPE myrange88 AS RANGE (SUBTYPE = int4);
CREATE TABLE rtest (r myrange88);
INSERT INTO rtest VALUES (myrange88(1,10));

CREATE TYPE myrange89 AS RANGE (SUBTYPE = int4, MULTIRANGE_TYPE_NAME = myrange89_multi);
CREATE TABLE mrtest (mr myrange89_multi);
INSERT INTO mrtest VALUES ('{[1,5],[10,20]}'::myrange89_multi);

CREATE TYPE myrange90 AS RANGE (SUBTYPE = varchar, COLLATION = "default");
CREATE TABLE vtest (v myrange90);
INSERT INTO vtest VALUES (myrange90('abc', 'xyz'));

CREATE TYPE myrange91 AS RANGE (SUBTYPE = int4, SUBTYPE_OPCLASS = int4_ops, MULTIRANGE_TYPE_NAME = myrange91_multi);
CREATE TABLE t91 (id serial, r myrange91, mr myrange91_multi);
INSERT INTO t91(r, mr) VALUES (myrange91(1,100), '{[1,10],[50,60]}'::myrange91_multi);
